import { test, expect } from '@playwright/test';

test.describe('Active Sessions Management', () => {
  test.beforeEach(async ({ page }) => {
    // Navigate to the application
    await page.goto('/');

    // Login with test credentials
    await page.getByLabel('Email').fill('testuser@example.com');
    await page.getByLabel('Password').fill('TestPassword123!');
    await page.getByRole('button', { name: /sign in/i }).click();

    // Wait for navigation to complete
    await page.waitForURL(/dashboard|home/);
  });

  test('should display all active sessions', async ({ page }) => {
    // Navigate to user profile or settings
    await page.getByRole('button', { name: /profile|settings/i }).click();

    // Click on sessions or security section
    await page.getByRole('link', { name: /sessions|active sessions/i }).click();

    // Verify the sessions page is loaded
    await expect(page.getByRole('heading', { name: /active sessions/i })).toBeVisible();

    // Verify at least one session is displayed
    const sessionItems = page.getByRole('listitem').filter({ has: page.getByText(/current session|browser|device/i) });
    await expect(sessionItems).toHaveCount(1, { timeout: 5000 });

    // Verify session details are visible
    await expect(page.getByText(/browser|device|location|last active/i)).toBeVisible();
  });

  test('should logout from a specific session', async ({ page }) => {
    // Navigate to user profile or settings
    await page.getByRole('button', { name: /profile|settings/i }).click();

    // Click on sessions or security section
    await page.getByRole('link', { name: /sessions|active sessions/i }).click();

    // Wait for sessions to load
    await expect(page.getByRole('heading', { name: /active sessions/i })).toBeVisible();

    // Find and click logout button for a specific session
    const logoutButton = page.getByRole('button', { name: /logout|sign out|end session/i }).first();
    await expect(logoutButton).toBeVisible();
    await logoutButton.click();

    // Verify confirmation dialog appears
    const confirmButton = page.getByRole('button', { name: /confirm|yes|logout/i });
    if (await confirmButton.isVisible()) {
      await confirmButton.click();
    }

    // Verify success message or session removal
    await expect(page.getByText(/session ended|logged out|removed/i)).toBeVisible({ timeout: 5000 });
  });

  test('should display session details including device and location', async ({ page }) => {
    // Navigate to user profile or settings
    await page.getByRole('button', { name: /profile|settings/i }).click();

    // Click on sessions or security section
    await page.getByRole('link', { name: /sessions|active sessions/i }).click();

    // Verify sessions page is loaded
    await expect(page.getByRole('heading', { name: /active sessions/i })).toBeVisible();

    // Verify session information is displayed
    const sessionInfo = page.getByText(/chrome|firefox|safari|edge/i);
    await expect(sessionInfo).toBeVisible();

    // Verify location information is shown
    const locationInfo = page.getByText(/location|city|country|ip address/i);
    await expect(locationInfo).toBeVisible({ timeout: 5000 });

    // Verify last active time is shown
    const lastActiveInfo = page.getByText(/last active|active|minutes ago|hours ago/i);
    await expect(lastActiveInfo).toBeVisible();
  });

  test('should mark current session appropriately', async ({ page }) => {
    // Navigate to user profile or settings
    await page.getByRole('button', { name: /profile|settings/i }).click();

    // Click on sessions or security section
    await page.getByRole('link', { name: /sessions|active sessions/i }).click();

    // Verify sessions page is loaded
    await expect(page.getByRole('heading', { name: /active sessions/i })).toBeVisible();

    // Verify current session is marked
    const currentSessionBadge = page.getByText(/current session|this device|current/i);
    await expect(currentSessionBadge).toBeVisible();

    // Verify current session does not have logout button or it's disabled
    const currentSessionSection = page.locator('div').filter({ has: page.getByText(/current session/i) }).first();
    const logoutInCurrentSession = currentSessionSection.getByRole('button', { name: /logout|sign out/i });

    // Either logout button should not exist or should be disabled
    const logoutExists = await logoutInCurrentSession.isVisible().catch(() => false);
    if (logoutExists) {
      await expect(logoutInCurrentSession).toBeDisabled();
    }
  });
});
